/**
 * Loaders for the preprocessed GTFS data (generated by scripts/build-gtfs.mjs,
 * served from /gtfs/ and cached by the service worker). Fetched once and
 * memoized in-memory.
 */
import { COMPLEX_NAMES } from './complexNames'

export interface Station {
  /** GTFS stop id (parent station). */
  id: string
  /** MTA complex id — stations sharing one collapse to a single complex. */
  complexId: string
  name: string
  /** Borough code: M, Bk, Bx, Q, SI. */
  borough: string
  lat: number
  lon: number
  /** Line short names serving this station, e.g. ["N", "W"]. */
  lines: string[]
}

/** route short name -> array of polylines, each a list of [lat, lon]. */
export type Shapes = Record<string, [number, number][][]>

/** A complex: one or more stations grouped under a single physical location. */
export interface Complex {
  id: string
  name: string
  borough: string
  stationIds: string[]
  lines: string[]
  lat: number
  lon: number
}

let stationsPromise: Promise<Station[]> | null = null
let shapesPromise: Promise<Shapes> | null = null

export function loadStations(): Promise<Station[]> {
  stationsPromise ??= fetch(`${import.meta.env.BASE_URL}gtfs/stations.json`).then(
    (r) => r.json(),
  )
  return stationsPromise
}

export function loadShapes(): Promise<Shapes> {
  shapesPromise ??= fetch(`${import.meta.env.BASE_URL}gtfs/shapes.json`).then(
    (r) => r.json(),
  )
  return shapesPromise
}

/** Group stations into complexes (centroid coords, merged line sets). */
export function groupComplexes(stations: Station[]): Complex[] {
  const byId = new Map<string, Station[]>()
  for (const s of stations) {
    const arr = byId.get(s.complexId)
    if (arr) arr.push(s)
    else byId.set(s.complexId, [s])
  }

  const complexes: Complex[] = []
  for (const [id, members] of byId) {
    const lines = [...new Set(members.flatMap((m) => m.lines))].sort()
    complexes.push({
      id,
      name: COMPLEX_NAMES[id] ?? members[0].name,
      borough: members[0].borough,
      stationIds: members.map((m) => m.id),
      lines,
      lat: members.reduce((s, m) => s + m.lat, 0) / members.length,
      lon: members.reduce((s, m) => s + m.lon, 0) / members.length,
    })
  }
  return complexes
}
